<?php
declare(strict_types=1);
require_once __DIR__.'/../libs/group-media.inc.php';$user=alphano_require_login();$u=alphano_user();$scope=(string)($_POST['scope']??$_GET['scope']??'corporazioni');$id=(int)($_POST['id']??$_GET['id']??0);
try{$g=group_media_context($scope,$id,$u);$message='';if($_SERVER['REQUEST_METHOD']==='POST'){alphano_require_csrf();$before=$g;$values=[];foreach(['stendardo','sfondotop'] as $field){$values[$field]=$g[$field];if(($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$values[$field]=group_media_upload($_FILES[$field],$scope,$id,$field);}if(!empty($_POST['shared']))$values['sfondotop']=$values['stendardo'];$db=ConnectDB();$db->beginTransaction();try{$db->execute('UPDATE '.$scope.' SET stendardo=?,sfondotop=? WHERE id=?',[$values['stendardo'],$values['sfondotop'],$id]);$g=array_replace($g,$values);alphano_record_activity('group-media-updated',(int)$u['id'],[['scope'=>$scope,'id'=>$id,'section'=>'pvt','role'=>'admin']],'Identità grafica aggiornata','Aggiornati stendardo e testata di '.$g['nome'],['before'=>$before,'after'=>$g]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}$message='Stendardo e testata aggiornati.';}}catch(DomainException $e){alphano_fail($e->getMessage(),$e->getCode());}
$h=static fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html lang="it"><head><meta charset="utf-8"><title>Identità grafica del gruppo</title></head><body class="ui-page"><main><header class="ui-page-heading" data-page-heading><span data-icon="shield"></span><div><h1><?=$h($g['nome'])?></h1><p>Stendardo, testata e anteprime condivise.</p></div><a class="action-btn" href="/<?=$scope?>/admin.php?<?=$scope==='corporazioni'?'corp':'org'?>=<?=$id?>" data-icon="settings">Gestione</a></header><?php if($message):?><p class="notice" role="status"><?=$h($message)?></p><?php endif;?><form class="ui-form group-media-editor" method="post" enctype="multipart/form-data"><input type="hidden" name="scope" value="<?=$scope?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="_csrf" value="<?=alphano_csrf_token()?>"><label>Stendardo ufficiale<input type="file" name="stendardo" accept="image/png,image/jpeg,image/webp"></label><?php if($g['stendardo']):?><img class="group-standard-preview" src="<?=$h($g['stendardo'])?>" alt="Stendardo attuale"><?php endif;?><label>Immagine panoramica della bottega o della sede<input type="file" name="sfondotop" accept="image/png,image/jpeg,image/webp"></label><label><input type="checkbox" name="shared" value="1"> Usa lo stendardo anche come testata</label><?php if($g['sfondotop']):?><img class="group-banner-preview" src="<?=$h($g['sfondotop'])?>" alt="Testata attuale"><?php endif;?><p>PNG, JPEG o WebP, massimo 10 MB. La stessa identità viene richiamata nell’elenco e nelle pagine del gruppo; su mobile gli elementi si adattano allo spazio disponibile.</p><button type="submit" data-icon="check">Salva identità grafica</button></form></main></body></html>
